    y: brick.y + brick.h + 2,
    r: 7,
    vx: 0,
    vy: UP,
  };
  state.ball.y -= 5;

  const mockCtx = {
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  frame(mockCtx, state);

  assert.ok(state.ball.vy === DOWN, 'ball should bounce DOWN after hitting the bottom of a brick');
});

