    y: brick.y - 1, 
    r: 7,
    vx: 0,
    vy: 1000, // Very fast
  };

  // We simulate the motion here because frame() doesn't move the ball, step() does.
  // But the prompt says "The ball passes through bricks".
  // If step() moves the ball, then frame() checks collision.

  // Simulate one step:
  const dt = 0.05;
  state.ball.y += state.ball.vy * dt; // y = -1 + 50 = 49.
  // Wait, 49 is inside the brick (48 to 68). So it will still collide.

  // Let's make it move further:
  state.ball.vy = 2000; 
  state.ball.y = brick.y - 1;
  state.ball.y += state.ball.vy * dt; // y = -1 + 100 = 99.
  // Now y = 99. Brick is at 48-68. Ball is at 92-106.
  // No collision!

  const mockCtx = {
    fillRect: () => {},
    beginPath: () => {},
    arc: () => {},
    fill: () => {},
    fillText: () => {},
  };

  frame(mockCtx, state);

  assert.equal(brick.alive, false, 'brick should be broken even if the ball tunneled through');
});

