import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame,
  UP,
  DOWN,
  resolveCollisions,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

test('resolveCollisions: ball bouncing off the bottom of a brick', () => {
  const state = createState(1);
  state.bricks = [state.bricks[0]];
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y + brick.h + 2,
    r: 7,
    vx: 0,
    vy: UP,
  };
  state.ball.y -= 5;

  resolveCollisions(state);

  assert.ok(state.ball.vy === DOWN, 'ball should bounce DOWN after hitting the bottom of a brick');
});

test('resolveCollisions: no double-bounce on the same axis in one frame', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];
  state.ball = {
    x: b1.x + b1.w + 4,
    y: b1.y + b1.h / 2,
    r: 7,
    vx: 100,
    vy: 0,
  };

  resolveCollisions(state);
  assert.ok(state.ball.vx < 0, 'ball should be moving LEFT after colliding with a wall of bricks');
});

test('step: ball does not tunnel through bricks at high speed', () => {
  const state = createState(10);
  const brick = state.bricks[0];
  state.ball = {
    x: brick.x + brick.w / 2,
    y: brick.y - 1,
    r: 7,
    vx: 0,
    vy: 2000,
  };

  // We test via step(), which now uses sub-stepping.
  // vy = 2000, dt = 0.05 => distance = 100.
  // Brick height = 20. 100 > 20, so it would tunnel without sub-stepping.
  step(state, 0.05);

  assert.equal(brick.alive, false, 'brick should be broken even if the ball was moving fast');
});
